def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Build lightweight views of opponent/my actions
    opp_defects = 0
    my_defects = 0
    for m, o in history:
        if o == 'D':
            opp_defects += 1
        if m == 'D':
            my_defects += 1

    last_m, last_o = history[-1]
    rounds_left = 100 - n

    # --- Final rounds: exploit forgiving cooperators safely ---
    if rounds_left <= 2:
        # If opponent has never defected on us, take the last payoff.
        if opp_defects == 0:
            return 'D'
        # If opponent is very cooperative, defect on final rounds.
        if opp_defects * 4 <= n:
            return 'D'
        # Otherwise mirror last move to avoid being exploited.
        return last_o

    # --- Very cooperative opponent: lock in mutual cooperation ---
    if opp_defects == 0:
        return 'C'
    if opp_defects * 5 <= n and last_o == 'C':
        return 'C'
    if opp_defects * 10 <= n:
        # Rare probe to test exploitability, but only if we've been very cooperative
        if n > 20 and n % 37 == 0 and my_defects * 20 < n:
            return 'D'
        return 'C'

    # --- Very defection-heavy opponent: punish, but try occasional reset ---
    if opp_defects * 2 >= n:
        # Detect if opponent has just cooperated after a long defect streak;
        # reward that with cooperation to encourage recovery.
        if last_o == 'C' and n >= 2 and history[-2][1] == 'D':
            return 'C'
        # Rare forgiveness to break mutual-DD deadlock
        if last_o == 'D' and last_m == 'D':
            if n >= 3 and history[-2][1] == 'D' and history[-3][1] == 'D':
                if rng.random() < 0.25:
                    return 'C'
        return 'D'

    # --- Moderate opponent ---
    # Count recent opponent behavior in a short window
    window = 8 if n >= 8 else n
    recent_opp_c = 0
    recent_opp_d = 0
    recent_cc = 0
    for i in range(n - window, n):
        m, o = history[i]
        if o == 'C':
            recent_opp_c += 1
        else:
            recent_opp_d += 1
        if m == 'C' and o == 'C':
            recent_cc += 1

    # Track opponent's defection streak
    opp_streak_d = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_streak_d += 1
        else:
            break

    # If opponent is in a long defection streak, punish firmly.
    if opp_streak_d >= 3:
        # But if they've been mostly cooperative overall, give one forgiveness
        if opp_defects * 4 <= n and rng.random() < 0.4:
            return 'C'
        return 'D'

    # Strong recent cooperation: cooperate
    if recent_opp_c >= window - 1:
        return 'C'

    # If we're stuck in DD: attempt to restore cooperation
    if last_m == 'D' and last_o == 'D':
        # If opponent has shown cooperation recently, cooperate to reset
        if recent_opp_c >= 2:
            return 'C'
        if rng.random() < 0.35:
            return 'C'
        return 'D'

    # Opponent just defected: retaliate, but with forgiveness
    if last_o == 'D':
        # Forgive if overall opponent has been fairly cooperative
        if opp_defects * 5 <= n:
            if rng.random() < 0.35:
                return 'C'
            return 'D'
        # Otherwise, stern but occasionally test forgiveness
        if opp_streak_d == 1 and rng.random() < 0.2:
            return 'C'
        return 'D'

    # Opponent cooperated last: cooperate, but occasionally probe
    if last_o == 'C':
        # If we defected and opponent still cooperated, they're forgiving;
        # don't over-exploit in early/mid game, but probe rarely.
        if last_m == 'D' and n > 15 and n % 23 == 0:
            return 'D'
        return 'C'

    return 'C'
